8	/**
9	 * The single duplicate check for creating an owner: rejects a request whose derived
10	 * {@link Owner#getIdentityKey() identity key} — normalized telephone, email and household id — equals
11	 * that of an existing owner. It subsumes the former separate telephone, email and household checks:
12	 * because the telephone is part of the key, two members of one household with different telephones
13	 * have different keys and are both allowed; only an exact full-key match is a duplicate.
14	 *
15	 * <p>Runs after {@link AssignHousehold} so the new owner carries its final {@code householdId}, and
16	 * before {@link SaveOwner} so a collision is rejected with 409 before anything is persisted. Only
17	 * owners sharing the (already normalized) telephone can share the whole key, so those are the
18	 * candidates compared.
19	 */
20	public class EnsureUniqueIdentity {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DuplicateIdentityException {
23	        String identityKey = owner.getIdentityKey();
24	        for (Owner existing : ownerRepository.findByTelephone(owner.getTelephone())) {
25	            if (identityKey.equals(existing.getIdentityKey())) {
26	                throw new DuplicateIdentityException(identityKey);
27	            }
28	        }
