6	/**
7	 * Converts a raw telephone into E.164 form. A leading {@code '+'} and country code are kept
8	 * when present; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
9	 * is dropped from the national digits. Spaces, dashes and brackets are stripped, and the result
10	 * must carry 8 to 15 digits after the {@code '+'}.
11	 *
12	 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and {@code "+64 21 123 456"}
13	 * becomes {@code "+6421123456"}.
14	 *
15	 * <p>Where the country code has a known fixed national-number length, that length is enforced:
16	 * {@code +61} requires 9 national digits and {@code +1} requires 10. A number whose national
17	 * part is the wrong length for its country code is rejected. Country codes with no known rule
18	 * are constrained only by the general 8-to-15-digit bound.
19	 */
20	final class E164Telephone {
21	
22	    /** Country code assumed when the number carries no explicit {@code '+'} prefix. */
23	    private static final String DEFAULT_COUNTRY_CODE = "61";
24	
25	    /** Spaces, dashes and brackets, which carry no meaning in E.164. */
26	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
27	
28	    /** A valid E.164 body: 8 to 15 digits following the {@code '+'}. */
29	    private static final Pattern E164_DIGITS = Pattern.compile("\\d{8,15}");
30	
31	    /** Country code to the exact national-number length it requires. */
32	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
33	
34	    private E164Telephone() {
35	    }
36	
37	    /**
38	     * @param raw the telephone as supplied by the client.
39	     * @return the E.164 string (e.g. {@code "+61412345678"}), or {@code null} if {@code raw}
40	     *         cannot form a valid E.164 number.
41	     */
42	    static String format(String raw) {
43	        if (raw == null) {
44	            return null;
45	        }
46	        String cleaned = SEPARATORS.matcher(raw).replaceAll("");
47	        String digits;
48	        if (cleaned.startsWith("+")) {
49	            digits = cleaned.substring(1);
